# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe DeliverInvoiceOperationJob do
  # "Until later issues register their adapters, every owner maps to a retryable \"adapter not available\" error."
  # "It calls the adapter's `commit` or `abort`, sets `delivered_at` only on a settled outcome, and otherwise keeps the row and increments `attempts`."
  it "counts an attempt and keeps the row when no adapter is registered for the current owner" do
    operation_id = SecureRandom.uuid
    InvoiceOperationIntent.create!(
      company_id: 1, invoice_id: 10, operation_id:, state: "committed",
      generation: 1, disposition: "active", desired_entry_ids: [3]
    )
    row = InvoiceOperationOutboxItem.create!(
      company_id: 1, invoice_id: 10, operation_id:, kind: "commit",
      payload: {
        "company_id" => 1, "invoice_id" => 10, "operation_id" => operation_id,
        "generation" => 1, "disposition" => "active", "desired_entry_ids" => [3]
      }
    )

    expect { described_class.perform_now(row.id) }.not_to raise_error

    expect(row.reload.delivered_at).to be_nil
    expect(row.attempts).to eq(1)
    expect(described_class.queue_name).to eq("invoice_operations")
  end
end

RSpec.describe DeliverInvoiceOperationJob do
  # "an undelivered commit row is delivered once and a second delivery changes nothing"
  # The invoice id names no invoice row: the request must come from the stored
  # outbox row and intent, never from the invoice.
  it "delivers an undelivered commit row once from its stored intent and a second delivery changes nothing" do
    operation_id = SecureRandom.uuid
    InvoiceOperationIntent.create!(
      company_id: 7, invoice_id: 99_999, operation_id:, state: "committed", generation: 3,
      disposition: "retained", desired_entry_ids: [5, 4]
    )
    item = InvoiceOperationOutboxItem.create!(
      company_id: 7, invoice_id: 99_999, operation_id:, kind: "commit",
      payload: { "company_id" => 7, "invoice_id" => 99_999, "operation_id" => operation_id,
                 "generation" => 3, "disposition" => "retained", "desired_entry_ids" => [4, 5] }
    )
    settled = Invoices::ReservationOutcome.new(state: "committed", conflicts: [], counts: {})
    adapter = RecordingReservationAdapter.new(prepare: settled, commit: settled, abort: settled)

    described_class.perform_now(item.id, reservations: adapter)
    first_delivery = item.reload.attributes.slice("delivered_at", "attempts")
    described_class.perform_now(item.id, reservations: adapter)

    expect(adapter.requests.size).to eq(1)
    expect(adapter.requests.first).to have_attributes(
      company_id: 7, invoice_id: 99_999, operation_id:, generation: 3, disposition: "retained", entries: [4, 5]
    )
    expect(first_delivery["delivered_at"]).to be_present
    expect(item.reload.attributes.slice("delivered_at", "attempts")).to eq(first_delivery)
    expect(described_class.queue_name).to eq("invoice_operations")
  end
end

RSpec.describe DeliverInvoiceOperationJob do
  # "It calls the adapter's `commit` or `abort`, sets `delivered_at` only on a settled outcome, and otherwise keeps the row and increments `attempts`."
  # With no injected adapter, every owner maps to "adapter not available" today.
  it "keeps an abort row undelivered and counts the attempt when no adapter is available" do
    operation_id = SecureRandom.uuid
    InvoiceOperationIntent.create!(
      company_id: 8, invoice_id: 55, operation_id:, state: "failed", generation: 1,
      disposition: "active", desired_entry_ids: [1]
    )
    item = InvoiceOperationOutboxItem.create!(
      company_id: 8, invoice_id: 55, operation_id:, kind: "abort",
      payload: { "company_id" => 8, "invoice_id" => 55, "operation_id" => operation_id,
                 "generation" => 1, "disposition" => "active", "desired_entry_ids" => [1] }
    )

    expect { described_class.perform_now(item.id) }.not_to raise_error

    expect(item.reload.delivered_at).to be_nil
    expect(item.attempts).to eq(1)
  end
end
